entries[425468] = { ["name"] = "Traumblüte", ["text"] = "Unbegrenzte Reichweite\nSofort\nDie Lebensenergie wiederhergestellter Treants lässt das Samenkorn des Lebens erblühen, wodurch 3 Spielercharaktere damit interagieren und eine magische Bindung mit dem Samenkorn eingehen können.\n\nDer letzte Spielercharakter, der eine Bindung eingeht, versprüht Smaragdenergie, wodurch ' Brennender Boden ' und ' Versengende Wurzeln ' gelöscht werden können, wobei das Samenkorn des Lebens jedoch Energie verliert." }
entries[425469] = { ["name"] = "Traumblüte", ["text"] = "Unbegrenzte Reichweite\nSofort\nDie Lebensenergie wiederhergestellter Treants lässt das Samenkorn des Lebens erblühen, wodurch 3 Spielercharaktere damit interagieren und eine magische Bindung mit dem Samenkorn eingehen können.\n\nDer letzte Spielercharakter , der eine Bindung eingeht, versprüht Smaragdenergie, wodurch ' Brennender Boden ' und ' Versengende Wurzeln ' gelöscht werden können, wobei das Samenkorn des Lebens jedoch Energie verliert." }
