entries[425509] = { ["name"] = "Durchtrennte Glut", ["text"] = "100 Meter Reichweite\nSofort\nBeschwört 4 Wurzeln, um ihre Kraft 15 Sek. lang einzusetzen, was Euch um 15% pro Wurzel verlangsamt. Eure nächsten 4 Einsätze von Nahkampffähigkeiten durchtrennen jeweils eine Wurzel und verursachen 1848 zusätzlichen Schattenflammenschaden, der auf Gegner in der Nähe aufgeteilt wird.\n\nDer Schaden erhöht sich mit jedem getroffenen Gegner, bis zu einem Maximum von 5." }
