entries[425517] = { ["name"] = "Leidenschaft", ["text"] = "Sofort\nBeim Verbrauchen von Wut besteht eine Chance, Euren nächsten Einsatz von 'Schildschlag' Eure auf dem Ziel aktiven Blutungseffekte verbrauchen zu lassen, was sofort 40% des verbleibenden Schadens Eurer Fähigkeiten 'Tiefe Wunden' und 'Verwunden' und 100% des verbleibenden Schadens von 'Donnerndes Gebrüll' verursacht und den von Euch erlittenen Schaden 5 Sek. lang um 10% verringert." }
entries[425518] = { ["name"] = "Errettung des Lichts", ["text"] = "Vergeltung\nWenn Ihr einen Himmelshammer herabruft, erhaltet Ihr einen Stapel von 'Errettung des Lichts'.\n\nWährend 'Aschewelle' und 'Hammer des Lichts' nicht verfügbar sind, verbraucht Ihr 60 Stapel von 'Errettung des Lichts', um 'Hammer des Lichts' kostenlos ein zusätzliches Mal einsetzen zu können.\n\nSchutz\nWenn Ihr einen Himmelshammer herabruft, erhaltet Ihr einen Stapel von 'Errettung des Lichts'.\n\nWährend 'Auge von Tyr' und 'Hammer des Lichts' nicht verfügbar sind, verbraucht Ihr 60 Stapel von 'Errettung des Lichts', um 'Hammer des Lichts' kostenlos ein zusätzliches Mal einsetzen zu können." }
