entries[425525] = { ["name"] = "Ewiger Feuersturm", ["text"] = "Unbegrenzte Reichweite\nSofort\nFyrakk verdunkelt den Himmel permanent und lässt regelmäßig brennende Meteore auf Spielercharaktere herabregnen. Jeder Meteor fügt Spielercharakteren innerhalb von 5 Metern um den Einschlagsort 398880 Schattenflammenschaden zu und es entsteht ein ' Wirbelnder Feuersturm '.\n\nDie Splitter der Meteore treffen auch Amirdrassil und fügen Spielercharakteren innerhalb von 4 Metern um die Einschlagsorte 725237 Schattenflammenschaden zu." }
entries[425526] = { ["name"] = "Toxisch", ["text"] = "Sofort\nDie Angriffe der Kreatur haben eine Chance, das Ziel zu vergiften und ihm so 9 Sek. lang alle 3 Sek. 10 Naturschaden zuzufügen." }
