entries[425885] = { ["name"] = "Suchendes Inferno", ["text"] = "Unbegrenzte Reichweite\nWirken in 2 sek.\nGlimmeron erschafft mehrmals ein ' Suchendes Inferno ', die sich alle auf zufällige Spielercharaktere fixieren. Spielercharaktere, die ein ' Suchendes Inferno ' berühren, werden mit ' Inferno ' belegt.\n\nWenn sie ihr Ziel erreichen oder 30 Sek. vergangen sind, explodieren sie und fügen allen Spielercharakteren 13 Feuerschaden zu. Die Explosion lässt alle Spielercharaktere 3 Sek. lang 2000 % mehr Schaden durch ' Suchendes Inferno ' erleiden." }
entries[425888] = { ["name"] = "Entfachendes Gewächs", ["text"] = "Unbegrenzte Reichweite\nSofort\nLarodar verdreht seinen feurigen Griff um die Natur und pflanzt Spielercharakteren für 15 Sek. Flammen ein, wodurch diese Bereiche von ' Brennender Boden ' hinterlassen. Neben einem Bereich von ' Brennender Boden ' ist der Effekt geringer." }
