entries[425957] = { ["name"] = "Splitternde Kohle", ["text"] = "Unbegrenzte Reichweite\nSofort\nBrennende Kohlestückchen werden von Knorrenwurzel weggeschleudert, fügen Spielercharakteren im Umkreis von 5 Metern um die Einschlagsorte 36262 Schattenflammenschaden zu und belegen sie mit ' Glutverkohlt '.\n\nJedes Kohlestückchen, das keinen Spielercharakter trifft, explodiert bei Kontakt mit dem Boden und fügt allen Spielercharakteren 108785 Schattenflammenschaden zu." }
entries[425958] = { ["name"] = "Schlängelnder Kriecherdrache: Behaartes Kinn", ["text"] = "Wirken in 3.5 sek. 3\nReagenzien:\nWildstoff (15), Glitzerndes Pergament (5), Schillerndes Wasser (8), Makellose Protodrachenschuppe (10), Erweckte Ordnung (4)\nBeute von:\nSmaragdgrüner Traum\n\nSchlängelnder Kriecherdrache: Behaartes Kinn\nDrachenwächtermanuskript\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Schaltet diese Anpassungsoption für den schlängelnden Kriecherdrachen frei, wenn der Gegenstand in der Nähe des Podiums der Transformation benutzt wird.\n\"Eine Schriftrolle, die einen mächtigen Protodrachen mit leuchtend grünen Schuppen beschreibt.\"" }
