entries[426018] = { ["name"] = "Suchendes Inferno", ["text"] = "Unbegrenzte Reichweite\nSofort\nGlimmeron erschafft mehrmals ein ' Suchendes Inferno ', die sich alle auf zufällige Spielercharaktere fixieren. Spielercharaktere, die ein ' Suchendes Inferno ' berühren, werden mit ' Inferno ' belegt.\n\nWenn sie ihr Ziel erreichen oder 30 Sek. vergangen sind, explodieren sie und fügen allen Spielercharakteren 90655 Feuerschaden zu. Die Explosion lässt alle Spielercharaktere 3 Sek. lang 2000% mehr Schaden durch ' Suchendes Inferno ' erleiden." }
