entries[426114] = { ["name"] = "Verdrehte Klinge", ["text"] = "100 Meter Reichweite\nSofort\nStößt eine verdrehte Klinge in Euer Ziel und verursacht 1448 körperlichen Schaden. Nach 3 Sek. strömt Schattenflamme aus der Klinge und sie kehrt zu Euch zurück, wobei sie 3548 Schattenflammenschaden verursacht, der zwischen dem Ziel und allen Gegnern in ihrer Bahn aufgeteilt wird.\n\nDer Schaden erhöht sich mit jedem getroffenen Gegner, bis zu einem Maximum von 5." }
entries[426115] = { ["name"] = "Dämonisch Manisch", ["text"] = "Gewährt Zugriff auf folgende Fähigkeiten:\n\nDämonenblitz\nSchickt die feurige Seele eines gefallenen Dämons auf den Gegner und fügt ihm (396.778% der Zaubermacht) Schattenflammenschaden zu. [ Dämonologie : Erzeugt 2 Seelensplitter. ]\nDämonischer Kern\nSobald Eure Wildwichtel ihre gesamte Energie verbraucht haben oder implodieren, besteht eine Chance von 10%, dass Ihr deren Lebensessenz absorbiert und so einen Stapel von 'Dämonischer Kern' erhaltet.\n\nWenn Eure beschworenen Schreckenspirscher verblassen, besteht eine Chance von 100%, dass Ihr deren Lebensessenz absorbiert und so einen Stapel von 'Dämonischer Kern' erhaltet.\n\n'Dämonischer Kern' verringert die Zauberzeit von 'Dämonenblitz' um 100%. Maximal 4 Stapel." }
