entries[426253] = { ["name"] = "Verdrehte Klinge", ["text"] = "100 Meter Reichweite\nSofort\nStößt eine verdrehte Klinge in Euer Ziel und verursacht 1448 körperlichen Schaden. Nach 3 Sek. strömt Schattenflamme aus der Klinge und sie kehrt zu Euch zurück, wobei sie 3548 Schattenflammenschaden verursacht, der zwischen dem Ziel und allen Gegnern in ihrer Bahn aufgeteilt wird.\n\nDer Schaden erhöht sich mit jedem getroffenen Gegner, bis zu einem Maximum von 5." }
entries[426254] = { ["name"] = "Herz von Amirdrassil" }
entries[426256] = { ["name"] = "Lodernde Vereinigung", ["text"] = "Unbegrenzte Reichweite\nSofort\n'Lodernde Dornen' verschmelzen zu Flammenkugeln, die sich auf Larodar zubewegen. Kugeln verursachen bei Kontakt 145047 Feuerschaden, erhöhen die kritische Trefferchance um 20% und verursachen 10 Sek. lang alle 0.5 Sek. 14505 Feuerschaden.\n\nKugeln, die Larodar erreichen, erhöhen dessen verursachten Feuerschaden 10 Sek. lang um 20%. Dieser Effekt ist stapelbar." }
entries[426259] = { ["name"] = "Pyroverprügeln", ["text"] = "100 Meter Reichweite\nSofort\nFackelfletscher hämmert mit einer Reihe flammender Hiebe auf den Boden vor sich und verursacht 4 Sek. lang alle 1 Sek. 2666894 Flammenschlagschaden." }
