entries[426261] = { ["name"] = "Unablässige Flamme", ["text"] = "30 Meter Reichweite\nWirken in 3 sek.\nRußschnauze beschwört in einem kegelförmigen Bereich vor ihm eine Fontäne aus Flammen, die 4 Sek. lang alle 0.5 Sek. 1333447 Feuerschaden verursacht." }
entries[426262] = { ["name"] = "Larodars feurige Träumereien", ["text"] = "Sofort\nCa. 1 Procs pro Minute\nEure Heilung hat eine Chance, 'Dornenwall' auf Euer Ziel zu wirken, wodurch 1995 Schaden absorbiert werden und Angreifer 240 Naturschaden erleiden. Wenn die Barriere durchbrochen wird, wird das Ziel im Verlauf von 6 Sek. um [Quellwert] Gesundheit geheilt. Wenn der Effekt ausläuft, ohne dass die Barriere durchbrochen wird, erhält das Ziel 10 Sek. lang 91 Vielseitigkeit.", ["unresolvedValues"] = true }
