entries[426268] = { ["name"] = "Chi-Ji, der Rote Kranich", ["text"] = "Sofort\nErhöht die Bewegungsgeschwindigkeit um 50%, gewährt Immunität gegen bewegungseinschränkende Effekte und 20 Sek. lang folgende Zauber.\n\nKranichschwarm\nFlattert ein kurzes Stück vorwärts.\n\nFlammende Nova\nEine Feuerexplosion wirft Euch zurück, was Gegnern innerhalb von 10 Metern Feuerschaden zufügt und Verbündete in diesem Bereich heilt.\n\nGefieder der Hoffnung\nChi-Ji wirft alle 2 Sek. eine Feder ab. Wer die Feder berührt, löst eine Salve von 'Flamme der Hoffnung' aus, die Gegnern Schaden zufügt und Verbündete heilt.\n\nFlamme der Hoffnung\nFügt Gegnern innerhalb von 30 Metern alle 2 Sek. Feuerschaden zu oder stellt bei Verbündeten in diesem Bereich Gesundheit wieder her. Betrifft 5 Ziele." }
entries[426269] = { ["name"] = "Dornenwall", ["text"] = "50 Meter Reichweite\nSofort\nEure Heilung hat eine Chance, 'Dornenwall' auf Euer Ziel zu wirken, wodurch 1995 Schaden absorbiert werden und Angreifer 240 Naturschaden erleiden. Wenn die Barriere durchbrochen wird, wird das Ziel im Verlauf von 6 Sek. um ( 582 * 3) Gesundheit geheilt. Wenn der Effekt ausläuft, ohne dass die Barriere durchbrochen wird, erhält das Ziel 10 Sek. lang 91 Vielseitigkeit." }
