entries[426283] = { ["name"] = "Leerenbogen", ["text"] = "30 Meter Reichweite\nWirken in 3 sek.\nTrifft einen Gegner mit Leerenenergie, die auf einen Gegner innerhalb von 6 Metern überspringt. Der Zauber wirkt sich auf bis zu 4 Ziele aus und fügt dem ersten Ziel 1939560 Schattenschaden und nachfolgenden Zielen immer weniger Schaden zu." }
entries[426284] = { ["name"] = "Finale Wunde", ["text"] = "100 Meter Reichweite\nSofort\nPlötzlicher Tod' sorgt dafür, dass Ihr bei Eurem nächsten Einsatz von 'Hinrichten' stark auf den Boden schlagt und dabei einen 'Donnerknall' erzeugt, der um 200% erhöhten Schaden verursacht. Außerdem blutet das Ziel von 'Hinrichten' und erleidet im Verlauf von 5 Sek. 50% des Schadens von 'Hinrichten'. Wenn die Blutung erneut angewendet wird, wird der verbleibende Schaden der neuen Blutung hinzugefügt." }
entries[426285] = { ["name"] = "Buschfeuer", ["text"] = "50 Meter Reichweite\nWirken in 2.5 sek.\nDer besudelte Treant wirft sengende Flora, die 40 Feuerschaden verursacht und die Bewegungsgeschwindigkeit aller Gegner innerhalb von 4 Metern um den Einschlagsort verringert." }
