entries[426287] = { ["name"] = "Splitternde Kohle", ["text"] = "Unbegrenzte Reichweite\nSofort\nBrennende Kohlestückchen werden von Knorrenwurzel weggeschleudert, fügen Spielercharakteren im Umkreis von 5 Metern um die Einschlagsorte 36262 Schattenflammenschaden zu und belegen sie mit ' Glutverkohlt '.\n\nJedes Kohlestückchen, das keinen Spielercharakter trifft, explodiert bei Kontakt mit dem Boden und fügt allen Spielercharakteren 108785 Schattenflammenschaden zu." }
entries[426288] = { ["name"] = "Glimmerons Größenwahn", ["text"] = "Sofort\nCa. 1 Procs pro Minute\nWenn Ihr Schaden erleidet, besteht eine Chance, dass Ihr mit ' Lodernder Zorn ' erfüllt werdet. Dadurch verursachen Eure Fähigkeiten 12 Sek. lang zusätzlich 124 Feuerschaden, der auf Gegner in der Nähe aufgeteilt wird, und Ihr erhaltet einen Schild in Höhe des durch diesen Effekt verursachten Schadens.\n\nDer Schaden erhöht sich pro getroffenem Gegner, bis zu einem Maximum von 5 Gegnern." }
entries[426289] = { ["name"] = "Lodernder Zorn", ["text"] = "40 Meter Reichweite\nSofort\nWenn Ihr Schaden erleidet, besteht eine Chance, dass Ihr mit ' Lodernder Zorn ' erfüllt werdet. Dadurch verursachen Eure Fähigkeiten 12 Sek. lang zusätzlich 124 Feuerschaden, der auf Gegner in der Nähe aufgeteilt wird, und Ihr erhaltet einen Schild in Höhe des durch diesen Effekt verursachten Schadens.\n\nDer Schaden erhöht sich pro getroffenem Gegner, bis zu einem Maximum von 5 Gegnern.\n(900ms Abklingzeit)" }
