entries[426339] = { ["name"] = "Igiras grausamer Nachtmahr", ["text"] = "Sofort\nCa. 1 Procs pro Minute\nEure Angriffe haben eine geringe Chance, aus Eurem Ziel Qualen hervorzubringen, um eine grausame Klinge zu manifestieren. Diese weist je nach Anzahl der Gegner in der Nähe unterschiedliche Qualitäten auf. Fügt einzelnen Zielen im Verlauf von 6 Sek. [Quellwert] Schattenflammenschaden oder verursacht 1661 Feuerschaden, der auf alle Gegner in der Nähe aufgeteilt wird.\n\nDer Schaden erhöht sich pro getroffenem Gegner, bis zu einem Maximum von 5 Gegnern.", ["unresolvedValues"] = true }
entries[426341] = { ["name"] = "Tindrons Vogelvorstellung", ["text"] = "Sofort\nCa. 1 Procs pro Minute\nEure schädlichen Zauber und Fähigkeiten haben eine Chance, ein Parlament lodernder Geistereulen zu beschwören, die im Sturzflug auf Euer Ziel niedergehen und ( 332 * 2 + 698 ) Feuerschaden verursachen, der auf alle Ziele in der Nähe aufgeteilt wird.\nDer Schaden erhöht sich pro getroffenem Gegner, bis zu einem Maximum von 5 Gegnern." }
