entries[426564] = { ["name"] = "Vernichtende Flamme", ["text"] = "50 Meter Reichweite\nSofort\nEure Zauber und Fähigkeiten haben eine geringe Chance, Euch für 20 Sek. 'Vernichtende Flamme' zu gewähren, wodurch Eure kritischen Treffer zusätzlich 50% Feuerschaden verursachen, der auf Gegner in der Nähe aufgeteilt wird. Die Flamme kann insgesamt [ 4682 * (1 + Vielseitigkeit)] Schaden verursachen, bevor sie erlischt, was durch kritische Treffer weiter erhöht werden kann.\n\nSchaden und Maximalwert erhöht sich mit jedem getroffenen Gegner, bis zu einem Maximum von 5 Gegnern." }
entries[426565] = { ["name"] = "IN FLAMMEN!", ["text"] = "100 Meter Reichweite\nSofort\nPflanzt den Setzling um und versucht 12 Sek. lang, seine Flammen zu löschen. Wenn Ihr den Setzling heilt, heilt Ihr auch bis zu 5 verletzte Verbündete insgesamt um den gleichen Betrag, welcher gleichmäßig aufgeteilt wird. Die Heilung wird für jeden Verbündeten erhöht, bis 12786 zusätzliche Heilung gewährt wurden.\n\nWenn der Setzling nach 12 Sek. noch am Leben ist, erhaltet Ihr als Dank 10 Sek. lang 59 Meisterschaft." }
entries[426566] = { ["name"] = "Schwelender Setzling", ["text"] = "Sofort\nPflanzt den Setzling um und versucht 12 Sek. lang, seine Flammen zu löschen. Wenn Ihr den Setzling heilt, heilt Ihr auch bis zu 5 verletzte Verbündete insgesamt um den gleichen Betrag, welcher gleichmäßig aufgeteilt wird. Die Heilung wird für jeden Verbündeten erhöht, bis 0 zusätzliche Heilung gewährt wurden.\n\nWenn der Setzling nach 12 Sek. noch am Leben ist, erhaltet Ihr als Dank 10 Sek. lang 0 Meisterschaft." }
entries[426568] = { ["name"] = "Natürliche Kraft", ["text"] = "Sofort\nErhöht 6 Sek. lang Euer Angriffstempo um 1% und Euren Naturschaden um 1%. Mehrere Instanzen von 'Natürliche Kraft' können sich überlappen, bis zu einem Maximum von 12 Instanzen." }
