entries[426578] = { ["name"] = "Geschmolzene Aufladung", ["text"] = "Sofort\n'Lavaeruption' verbrennt Euer Ziel und fügt ihm im Verlauf von 4 Sek. 10% zusätzlichen Schaden zu. Nach Verbrauchen von 'Urzeitliche Welle' treffen außerdem Eure nächsten 2 Einsätze von 'Lavaeruption' bis zu 3 zusätzliche Ziele, die von Eurem 'Flammenschock' betroffen sind, und fügen ihnen 65% des normalen Schadens zu." }
entries[426581] = { ["name"] = "Vergiftende Explosion", ["text"] = "100 Meter Reichweite\nSofort\n'Vergiften' ermächtigt sich selbst, was eine 'Vergiftende Explosion' auslöst, die allen Gegnern in der Nähe (90% der Angriffskraft) Naturschaden zufügt, während 'Vergiften' aktiv ist. Fügt Zielen über 5 Ziele hinaus verringerten Schaden zu. Wenn 'Vergiftende Explosion' einem Einzelziel Schaden zufügt, wird dieser um 30% erhöht." }
