entries[426588] = { ["name"] = "Betäubendes Geheimnis", ["text"] = "Die Abklingzeit und Energiekosten von 'Nierenhieb' sind um 100% verringert. 'Nierenhieb' erzeugt nun Schattenklone, die alle anderen Gegner in der Umgebung betäuben." }
entries[426589] = { ["name"] = "Nierenhieb", ["text"] = "100 Meter Reichweite\nSofort\nBenötigt Nahkampfwaffe\nFinishing-Move, der das Ziel betäubt . Hält pro Combopunkt länger an, bis zu maximal 8 Sek.:\n1 Punkt: 4 Sek.\n2 Punkte: 5 Sek.\n3 Punkte: 6 Sek.\n4 Punkte: 7 Sek.\n5 Punkte: 8 Sek." }
entries[426590] = { ["name"] = "Gefräßige Galle", ["text"] = "Sofort\nRaal setzt ' Gefräßige Galle ' frei, nachdem er einen siechenden Diener verschlungen hat und fügt allen Spielercharakteren 8 Sek. lang alle 1 Sek. 848557 Naturschaden zu.\n\nDieser Effekt ist stapelbar." }
entries[426591] = { ["name"] = "Blutschlunds Biss", ["text"] = "25 Energie Nahkampfreichweite\nSofort 45 sek. Abklingzeit\nSchlägt nach dem Ziel aus, verursacht (326.7% der Angriffskraft) Schattenschaden und lässt Eure nächsten 3 Finishing-Moves keine Energie verbrauchen.\n\nGewährt 3 Combopunkte." }
