entries[426594] = { ["name"] = "Schattenkunst", ["text"] = "Während 'Symbole des Todes' aktiv ist, löst Eure Fähigkeit 'Schattentechniken' 40% häufiger aus, speichert 1 zusätzlichen Combopunkt und Eure Finishing-Moves können gespeicherte Combopunkte verbrauchen, wenn genug gespeichert sind, um Eure Combopunkte voll aufzufrischen." }
entries[426595] = { ["name"] = "Schattentechniken", ["text"] = "Unbegrenzte Reichweite\nSofort\nEure automatischen Angriffe haben eine Chance von 28%, 4 Energie zu erzeugen und 1 Combopunkt zu speichern, bis zu einem Maximum von 10 Combopunkten.\n\nAngriffe, die Combopunkte erzeugen, können gespeicherte Combopunkte verbrauchen, um zusätzliche Combopunkte bis zum Maximum zu erzeugen." }
entries[426596] = { ["name"] = "Seelengeschoss", ["text"] = "40 Meter Reichweite\nWirken in 2.5 sek.\nVerschießt einen Blitz verkrüppelnder Energie, der dem Ziel 3151784 Schattenschaden zufügt. Das Tragen der Fokussierungsiris erhöht den Schaden von ' Seelengeschoss '." }
entries[426602] = { ["name"] = "Durchlöcherte Adern", ["text"] = "Sofort\nNachdem Ihr 4-mal mit [ Düstere Klinge : 'Düstere Klinge' / 'Meucheln'] angegriffen habt, verursacht Euer nächster Angriff, der Combopunkte erzeugt, 50% mehr Schaden." }
entries[426603] = { ["name"] = "Schlummernder Traum", ["text"] = "Sofort\nBeim Erleiden von Schaden gibt es eine Chance, dass Schlummernder Traum erblüht, Euch für 15 Sek. gegen 2084 Schaden abschirmt und Gedeihender Traum einen befreundeten Verbündeten innerhalb von 30 Metern markiert.\n\nWenn Ihr Euch einem mit Gedeihender Traum markierten Verbündeten bis auf 5 Meter nähert, wird er erweckt und schirmt Euch und Euren Verbündeten im Verlauf von 15 Sek. gegen 1389 Schaden ab." }
