entries[426629] = { ["name"] = "Brennender Boden", ["text"] = "Unbegrenzte Reichweite\nSofort\nDer Tempel wird von Flammenfeldern überzogen, die alle 1.5 Sek. 108785 Feuerschaden verursachen.\n\nLarodars ' Verbrennende Präsenz ', seine feurigen Eigenschaften und versengenden Wurzeln sowie die Flammenfelder breiten den brennenden Boden noch weiter aus.\n\n' Traumblüte ' dämmt diese Felder wieder ein." }
