entries[426647] = { ["name"] = "Bester Freund von Pip", ["text"] = "Sofort\nSchließt Euch dem Traumteam an und erhaltet ( 266 / 12) von Pips Meisterschaft, Urctos' Vielseitigkeit oder Aerwynns kritischem Trefferwert, je nachdem, wer Euer derzeitiger bester Freund ist.\n\nEure Zauber und Fähigkeiten haben die Chance, einen zufälligen neuen besten Freund zu markieren, der Euch den entsprechenden passiven Bonus gewährt und diesen auf 266 erhöht, bevor er im Verlauf von 12 Sek. abnimmt." }
entries[426648] = { ["name"] = "Gesangsstab des Kranichs", ["text"] = "Sofort\nIntoniert einen inspirierenden Gesang, während Ihr weniger als 50% Gesundheit habt.\nIntoniert eine flammende Hymne, während Ihr mehr als 50% Gesundheit habt.\n\nInspirierender Gesang\nStellt bei den 3 am stärksten verletzten Gruppenmitgliedern innerhalb von 50 Metern alle 5 Sek.(75% der Zaubermacht + 75% der Angriffskraft) Gesundheit wieder her.\n\nFlammende Hymne\nFügt den 3 am stärksten verwundeten Gegnern innerhalb von 40 Metern alle 5 Sek. (50% der Zaubermacht + 50% der Angriffskraft) Feuerschaden zu." }
